import{_ as o,o as u,c as q,ag as a}from"./chunks/framework.CukOUUOK.js";const g=JSON.parse('{"title":"谁在给笼子拆锁：从感知驯化到主动辩护——论普通人如何一步步交出自由","description":"引子：一个被严重低估的变量 在所有关于法治倒退的讨论中，最被低估的变量不是权力的扩张本身，而是普通人主动替权力扩张辩护的热情。 翻开任何一个涉及公共事件的评论区，你都能看到这样一类人：他们不是体制内的…","frontmatter":{"title":"谁在给笼子拆锁：从感知驯化到主动辩护——论普通人如何一步步交出自由","categories":"权力与制度","tags":["社会心理","权力","言论空间"],"description":"引子：一个被严重低估的变量 在所有关于法治倒退的讨论中，最被低估的变量不是权力的扩张本身，而是普通人主动替权力扩张辩护的热情。 翻开任何一个涉及公共事件的评论区，你都能看到这样一类人：他们不是体制内的…","date":"2026-08-29T12:00:00.000Z"},"headers":[],"relativePath":"posts/2026-08-29-who-unlocks-the-cage.md","filePath":"posts/2026-08-29-who-unlocks-the-cage.md","lastUpdated":1789992750000}'),r={name:"posts/2026-08-29-who-unlocks-the-cage.md"};function p(e,t,n,s,h,l){return u(),q("div",null,[...t[0]||(t[0]=[a('<h1 id="谁在给笼子拆锁-从感知驯化到主动辩护——论普通人如何一步步交出自由" tabindex="-1">谁在给笼子拆锁：从感知驯化到主动辩护——论普通人如何一步步交出自由 <a class="header-anchor" href="#谁在给笼子拆锁-从感知驯化到主动辩护——论普通人如何一步步交出自由" aria-label="Permalink to &quot;谁在给笼子拆锁：从感知驯化到主动辩护——论普通人如何一步步交出自由&quot;">​</a></h1><h2 id="引子-一个被严重低估的变量" tabindex="-1">引子：一个被严重低估的变量 <a class="header-anchor" href="#引子-一个被严重低估的变量" aria-label="Permalink to &quot;引子：一个被严重低估的变量&quot;">​</a></h2><p>在所有关于法治倒退的讨论中，最被低估的变量不是权力的扩张本身，而是普通人主动替权力扩张辩护的热情。</p><p>翻开任何一个涉及公共事件的评论区，你都能看到这样一类人：他们不是体制内的人，不靠权力吃饭，甚至本身就是权力滥用的潜在受害者——但他们比谁都积极地替权力辩护。气枪案判了，他们说&quot;法律太明确了才误伤人&quot;；掏鸟案判了，他们说&quot;大学生本来就不该掏&quot;；有人因网上发言被拘，他们说&quot;肯定是他自己表述有问题&quot;；有人因批评政策被处理，他们说&quot;动机不纯，活该&quot;。</p><p>这不是少数人的怪癖。这是一种大规模的、系统性的认知现象。而正是这种现象的存在，使得权力的每一次扩张都获得了民间的&quot;自愿配合&quot;——权力甚至不需要动用强制力，因为已经有人替它完成了说服工作。</p><p>但这种现象不是凭空产生的。在它之前，有一个更隐蔽的前置过程——文艺与舆论环境如何系统性地切除公众的痛觉与追问能力。如果说那个过程解决的是&quot;如何让你不再感到疼痛&quot;的问题，那么本文要追问的是一个更荒谬的现象——你不仅不感到疼痛了，你还主动替那个制造疼痛的结构辩护，甚至真心相信自己在做正确的事。</p><h2 id="上篇-感知的切除——你如何变得不再疼痛" tabindex="-1">上篇：感知的切除——你如何变得不再疼痛 <a class="header-anchor" href="#上篇-感知的切除——你如何变得不再疼痛" aria-label="Permalink to &quot;上篇：感知的切除——你如何变得不再疼痛&quot;">​</a></h2><h3 id="一、被制造出来的-无感" tabindex="-1">一、被制造出来的&quot;无感&quot; <a class="header-anchor" href="#一、被制造出来的-无感" aria-label="Permalink to &quot;一、被制造出来的&quot;无感&quot;&quot;">​</a></h3><p>一个社会的多数人之所以会主动替权力辩护，前提条件是：他们首先丧失了对权力滥用的痛感。</p><p>这种丧失不是自然发生的。它是文艺生产、舆论引导和教育系统长期协作的结果。当荧幕上反复播放的是&quot;正义终将到来&quot;&quot;上面会解决的&quot;&quot;大方向是好的&quot;这类叙事时，观众对现实中正在发生的权力侵害就逐渐丧失了敏感度。不是因为他们不善良，而是因为他们的感知通道被系统性地窄化了——他们被训练成只能感知到&quot;被允许感知的东西&quot;。</p><p>这种感知驯化的核心机制是：<strong>不禁止你感受，而是替你定义什么值得感受。</strong> 当所有文艺作品都在重复同一种情感模式——&quot;小人物受委屈→上面出面解决→大团圆&quot;——观众就逐渐丧失了想象&quot;没有上面出面&quot;的能力。他们不是不能愤怒，而是他们的愤怒被预设了方向：只能指向&quot;具体的坏人&quot;，不能指向&quot;结构本身&quot;。</p><h3 id="二、痛觉切除的政治后果" tabindex="-1">二、痛觉切除的政治后果 <a class="header-anchor" href="#二、痛觉切除的政治后果" aria-label="Permalink to &quot;二、痛觉切除的政治后果&quot;">​</a></h3><p>一个丧失了痛觉的社会，表面上看起来非常&quot;稳定&quot;。没有人抗议，没有人追问，没有人制造麻烦。但这种稳定的代价是：社会失去了自我纠错的能力。</p><p>当一个普通人的邻居被冤案碾碎时，他不会感到疼痛——因为文艺叙事已经告诉他&quot;这是个案&quot;&quot;大方向是好的&quot;&quot;别太较真&quot;。当一个陌生人在网上因发言被拘时，他不会感到不安——因为舆论环境已经帮他完成了归因：&quot;肯定是他自己有问题&quot;&quot;苍蝇不叮无缝的蛋&quot;。</p><p><strong>痛觉的意义在于预警。手指触到火焰时的缩回反射，不是软弱，而是生存机制。一个丧失了痛觉的人，会把手放在火上烤到焦烂而不自知。一个丧失了社会痛觉的群体，会在自由被一寸寸蚕食的过程中保持微笑。</strong></p><p>这就是为什么接下来要讨论的现象如此令人不安：这些人不仅不感到疼痛了，他们还主动替那个制造疼痛的结构辩护——而且真心相信自己在做正确的事。</p><h2 id="中篇-判断力的交出——你如何主动替权力辩护" tabindex="-1">中篇：判断力的交出——你如何主动替权力辩护 <a class="header-anchor" href="#中篇-判断力的交出——你如何主动替权力辩护" aria-label="Permalink to &quot;中篇：判断力的交出——你如何主动替权力辩护&quot;">​</a></h2><h3 id="一、先承认一个事实-民间舆论不全是-拆锁" tabindex="-1">一、先承认一个事实：民间舆论不全是&quot;拆锁&quot; <a class="header-anchor" href="#一、先承认一个事实-民间舆论不全是-拆锁" aria-label="Permalink to &quot;一、先承认一个事实：民间舆论不全是&quot;拆锁&quot;&quot;">​</a></h3><p>在进入批判之前，必须首先做一个至关重要的区分，否则本文的全部论证都会被误读为&quot;精英知识分子居高临下地嘲笑普通人的恐惧&quot;。</p><p><strong>民间舆论对司法的影响，存在两种截然相反的方向。</strong></p><p><strong>第一种是&quot;修锁型舆论&quot;：要求规则更明确、程序更正当、权利保障更充分。</strong> 2016年的于欢案即为典型案例。于欢在母亲遭受极端侮辱的情况下持刀反击致一死三伤，一审以故意伤害罪判处无期徒刑。舆论的愤怒不是指向&quot;判得太重&quot;这个结果本身，而是指向一审法院对正当防卫条款的僵化适用——判决书几乎完全忽略了&quot;不法侵害正在进行&quot;这一时间要件的认定，也忽略了防卫人面对多人围殴时的恐惧与绝望。最终，二审改判有期徒刑五年，认定于欢的行为属于防卫过当。这一判决激活了沉睡多年的正当防卫条款，为后续昆山反杀案等一系列案件的处理提供了重要的司法先例。</p><p>同样，2018年昆山反杀案中，刘海龙持刀攻击于海明反被于海明夺刀反杀，检察机关最终认定于海明的行为属于正当防卫，不负刑事责任。舆论在其中扮演的角色，同样是<strong>要求司法更严格地适用正当防卫条款</strong>，而不是要求&quot;取消正当防卫的构成要件让法官看着办&quot;。</p><p>呼格吉勒图案、聂树斌案等冤案的平反，同样属于&quot;修锁型舆论&quot;——公众追问的是&quot;证据够不够&quot;&quot;程序对不对&quot;，而不是&quot;别搞那么多程序直接判了算了&quot;。</p><p><strong>第二种是&quot;拆锁型舆论&quot;：呼吁简化程序、降低证据标准、扩大打击范围、以&quot;目的&quot;而非&quot;行为&quot;定罪。</strong> 这正是本文批判的对象。</p><p><strong>区分这两种舆论的关键标准只有一个：它的诉求方向是&quot;让规则更明确&quot;，还是&quot;让规则更模糊&quot;？</strong> 前者是修锁，后者是拆锁。于欢案舆论要求的是&quot;正当防卫的认定标准应该更明确地保护防卫者&quot;——这是要求规则更明确。而&quot;法律太明确了才误伤人&quot;&quot;核心是看目的&quot;&quot;直接抓了算了&quot;——这些声音要求的是规则更模糊、裁量权更大。</p><p><strong>本文批判的从来不是&quot;民间舆论介入司法&quot;本身，而是其中特定方向的介入——那些以&quot;正义&quot;之名要求拆毁规则护栏的声音。</strong></p><h3 id="二、-明确规则害了我-一个因果倒置的认知陷阱" tabindex="-1">二、&quot;明确规则害了我&quot;：一个因果倒置的认知陷阱 <a class="header-anchor" href="#二、-明确规则害了我-一个因果倒置的认知陷阱" aria-label="Permalink to &quot;二、&quot;明确规则害了我&quot;：一个因果倒置的认知陷阱&quot;">​</a></h3><p>最常见的替权力辩护的逻辑是：<strong>&quot;你看，法律写得太明确了，1.8焦耳的标准卡死了，赵春华摆气球摊就被判了；掏16只鸟就够得上情节特别严重，大学生就被判了十年。要是法律写得模糊点，法官灵活处理，就不会出这种荒唐事。&quot;</strong></p><p>这个逻辑看似有同理心，实则把因果关系完全搞反了。</p><h3 id="赵春华案-被错怪的1-8焦耳" tabindex="-1">赵春华案：被错怪的1.8焦耳 <a class="header-anchor" href="#赵春华案-被错怪的1-8焦耳" aria-label="Permalink to &quot;赵春华案：被错怪的1.8焦耳&quot;">​</a></h3><p>2016年10月，天津51岁的赵春华在海河亲水平台摆设气球射击摊，被警方查获9支枪形物，其中6支经鉴定枪口比动能约为2.0焦耳/平方厘米，超过公安部2010年《公安机关涉案枪支弹药性能鉴定工作规定》所确定的1.8焦耳/平方厘米的枪支认定标准，一审被以非法持有枪支罪判处有期徒刑三年六个月。</p><p>这个标准从何而来？它并非经过立法程序制定，而是公安部2007年发布、2008年实施的《枪支致伤力的法庭科学鉴定判据》中确立的内部技术规范。有律师指出，1.8焦耳/平方厘米仅相当于军用枪支动能标准的1/154，甚至低于乒乓球、羽毛球的扣杀力度，与《枪支管理法》第46条规定的枪支本质特征——&quot;足以致人伤亡或者丧失知觉&quot;——相去甚远。有公安系统学者承认，这一数值仅是给人体最脆弱部位——裸露的眼睛——造成损伤的临界值，是否能以特殊情况作为人体整体的致伤力标准，&quot;仍值得探讨&quot;。</p><p>赵春华案的荒谬，<strong>从来不是1.8焦耳写得太清楚，而是1.8焦耳这个标准本身就是公安部一纸文件拍脑袋定的</strong>——没有经过立法程序，没有经过公众讨论，一把玩具水枪都能超过这个数值，直接把玩具划成了&quot;枪支&quot;。有律师指出，这是典型的&quot;严格性立法、普遍性违法、选择性执法&quot;问题。</p><p>按&quot;模糊更好&quot;的逻辑，正确做法是什么？把1.8焦耳删了，改成&quot;具有致伤可能性的发射器具&quot;，让法官&quot;看着办&quot;？然后呢？法官一句&quot;这枪看着像枪，有危险性&quot;，直接判了。你连1.8焦耳这个最低限度的客观锚点都没了，连上诉的依据都找不到。</p><p>事实上，赵春华案最终推动的恰恰是<strong>标准的修正</strong>而非<strong>标准的消灭</strong>。2018年3月，最高人民法院、最高人民检察院联合发布《关于涉以压缩气体为动力的枪支、气枪铅弹刑事案件定罪量刑问题的批复》，明确要求审理此类案件&quot;不唯数值论&quot;，应综合考量枪支致伤力、外观用途、行为人主观认知与作案动机，全面评估社会危害性，确保罪责刑相适应。2024年，人民法院案例库进一步收录参考案例，明确对于以收藏、娱乐为目的、枪口比动能较低的涉枪行为，情节显著轻微的不作为犯罪处理。</p><p>这恰恰证明：<strong>标准烂了，应该改标准，不是消灭标准。有明确标准，你至少知道红线在哪，至少能拿着条文去挑战它本身；模糊规则之下，你连挑战的靶子都找不到。</strong></p><h3 id="掏鸟案-被简化的事实与被错置的愤怒" tabindex="-1">掏鸟案：被简化的事实与被错置的愤怒 <a class="header-anchor" href="#掏鸟案-被简化的事实与被错置的愤怒" aria-label="Permalink to &quot;掏鸟案：被简化的事实与被错置的愤怒&quot;">​</a></h3><p>河南闫啸天案同样如此。2014年7月，闫啸天与同乡王亚军在树林内猎捕16只燕隼（国家二级保护动物）并通过网络售卖，2015年一审被以非法猎捕珍贵、濒危野生动物罪判处有期徒刑十年六个月。舆论将其简化为&quot;大学生掏鸟被判十年&quot;，引发一边倒的同情。</p><p>但事实远比标题复杂：闫啸天是&quot;河南鹰猎兴趣交流群&quot;成员，曾网上非法收购凤头鹰转手出售；在兜售燕隼时刻意标注&quot;阿穆尔隼&quot;；捕猎、收购、倒卖形成了完整的犯罪链条，且不止实施了一次。根据司法解释，隼类10只以上即构成&quot;情节特别严重&quot;，起刑十年，法院判决完全在法定幅度内。</p><p>真正值得讨论的问题是：司法解释的数量标准是否合理？当事人的主观认知程度如何？量刑是否应当引入生态修复等替代性处罚？但舆论将这一切简化为&quot;法律太明确才判这么重&quot;，恰恰回避了对具体制度设计的精细讨论，转而呼吁一种更模糊的、更依赖&quot;灵活处理&quot;的司法模式。</p><p>中国政法大学阮齐林教授坦承：&quot;仅根据数量和保护的动物级别来定罪量刑，有的时候会过于刻板。&quot;但他同时强调，这&quot;依然无法改变此案判决的合法性&quot;。问题的解法应当是推动量刑标准的精细化改革，而非退回到&quot;法官看着办&quot;的前法治状态。</p><h3 id="因果倒置的认知机制" tabindex="-1">因果倒置的认知机制 <a class="header-anchor" href="#因果倒置的认知机制" aria-label="Permalink to &quot;因果倒置的认知机制&quot;">​</a></h3><p>为什么那么多人看不到这一点？因为<strong>因果倒置是人类认知中最顽固的陷阱之一</strong>。当一个荒谬的结果发生时，人们本能地寻找&quot;最近的变量&quot;作为原因。1.8焦耳是判决书上最显眼的数字，所以它成了&quot;罪魁祸首&quot;。而那个真正导致荒谬的原因——公安部未经立法程序单方面设定枪支认定标准——离普通人的认知太远了，远到他们根本意识不到它的存在。</p><p>于是，一个完美的认知闭环形成了：荒谬判决→归因于&quot;规则太明确&quot;→呼吁&quot;模糊一点更好&quot;→模糊规则导致更大的荒谬→再次归因于&quot;规则不够好&quot;→呼吁&quot;让执法者灵活处理&quot;→更大的荒谬……</p><p><strong>这个闭环永远不会被打破，因为每一次失败都被归因于&quot;规则本身的问题&quot;，而不是&quot;权力不受约束的问题&quot;。</strong></p><h3 id="三、口袋罪的前世今生-模糊规则的真正代价" tabindex="-1">三、口袋罪的前世今生：模糊规则的真正代价 <a class="header-anchor" href="#三、口袋罪的前世今生-模糊规则的真正代价" aria-label="Permalink to &quot;三、口袋罪的前世今生：模糊规则的真正代价&quot;">​</a></h3><h3 id="流氓罪-一部-模糊规则-的血泪史" tabindex="-1">流氓罪：一部&quot;模糊规则&quot;的血泪史 <a class="header-anchor" href="#流氓罪-一部-模糊规则-的血泪史" aria-label="Permalink to &quot;流氓罪：一部&quot;模糊规则&quot;的血泪史&quot;">​</a></h3><p>要理解&quot;模糊规则&quot;的真正代价，必须回到中国当代法制史上最具代表性的口袋罪——流氓罪。</p><p>1979年《刑法》第160条规定：&quot;聚众斗殴，寻衅滋事，侮辱妇女或者进行其他流氓活动，破坏公共秩序，情节恶劣的，处七年以下有期徒刑、拘役或者管制。&quot;其中&quot;其他流氓活动&quot;这一兜底条款，使流氓罪成为一个典型的&quot;口袋罪&quot;——跳舞、口角、多段恋爱关系等行为都可被归入。</p><p>1983年&quot;严打&quot;期间，流氓罪的量刑上限被直接提升至死刑。在&quot;从重从快&quot;的政策导向下，仅第一年全国就有2.4万人被判处死刑。陕西女子马燕秦因与多名异性保持恋爱关系、参与私人舞会，被认定为&quot;流氓集团首要分子&quot;，以流氓罪判处死刑。青年男女在公园拥抱亲吻被认定为&quot;流氓行为&quot;，朋友聚会饮酒划拳被定性为&quot;寻衅滋事型流氓罪&quot;。</p><p>这就是&quot;模糊规则&quot;的终极后果：<strong>当法律不告诉你什么是犯罪时，一切行为都可能是犯罪。</strong></p><p>1997年《刑法》修订正式废除流氓罪，将其拆解为寻衅滋事罪、聚众斗殴罪、强制猥亵罪等多个边界清晰的罪名。这一变革被法学界视为中国法治从&quot;治人&quot;到&quot;治法&quot;的关键一跃。</p><h3 id="寻衅滋事罪-口袋罪基因的-次生遗传" tabindex="-1">寻衅滋事罪：口袋罪基因的&quot;次生遗传&quot; <a class="header-anchor" href="#寻衅滋事罪-口袋罪基因的-次生遗传" aria-label="Permalink to &quot;寻衅滋事罪：口袋罪基因的&quot;次生遗传&quot;&quot;">​</a></h3><p>然而，流氓罪虽死，其基因未灭。</p><p>寻衅滋事罪从流氓罪中分解而来，或多或少遗传了&quot;口袋罪&quot;的基因。中国政法大学教授罗翔多次指出，寻衅滋事罪最大的问题在于其构成要件的模糊性——&quot;随意&quot;&quot;任意&quot;&quot;情节恶劣&quot;&quot;造成秩序严重混乱&quot;等表述缺乏明确的客观判断标准，极大地依赖于司法人员的主观判断，导致该罪成为一个&quot;口袋&quot;，可以将许多其他罪名难以规制的行为装进去。</p><p>北京大学教授陈兴良指出，司法解释将&quot;寻求刺激、发泄情绪、逞强耍横&quot;等&quot;流氓动机&quot;作为认定该罪的重要主观要素，然而探究行为人的内心动机在司法实践中极为困难，且容易导致主观归罪。华东政法大学教授魏昌东更揭示，在2018年后的&quot;运动式&quot;治理中，本不符合&quot;无事生非&quot;要件的拆迁征收冲突事件，被以寻衅滋事罪追惩的不在少数。</p><p>全国政协委员朱征夫自2008年担任全国人大代表起，连续十余年提案呼吁取消寻衅滋事罪。他指出，该罪存在三大缺陷：构成要件不明确；与故意伤害、侮辱、抢劫等罪名竞合，属于重复立法；存在体系逻辑悖论——毁损财物2000元可构成寻衅滋事罪，但故意毁坏财物罪需5000元，且寻衅滋事罪的法定最高刑（五年）反而重于故意毁坏财物罪（三年）。</p><p>南京大学法学院孙国祥教授在2024年的研究中确认，寻衅滋事罪处罚范围不断扩大而形成的&quot;口袋化&quot;倾向&quot;是不争的事实&quot;，其犯罪圈不断扩大的成因复杂，包括罪状表述模糊、动机被虚置、司法解释的再解释进一步扩大适用范围等。</p><h3 id="于凯案-当-呼吁修改模糊规则-本身成为犯罪" tabindex="-1">于凯案：当&quot;呼吁修改模糊规则&quot;本身成为犯罪 <a class="header-anchor" href="#于凯案-当-呼吁修改模糊规则-本身成为犯罪" aria-label="Permalink to &quot;于凯案：当&quot;呼吁修改模糊规则&quot;本身成为犯罪&quot;">​</a></h3><p>最具讽刺意味的是：呼吁修改模糊规则的人，恰恰被模糊规则所吞噬。</p><p>律师于凯长期呼吁废除寻衅滋事罪。2023年8月，他联合其他四位律师向全国人大提交《关于废除寻衅滋事罪的立法建议》。2024年7月，因&quot;违规炒作案件&quot;被青岛市司法局处以停止执业一年的行政处罚。2026年3月，他再次因建议废除寻衅滋事罪，被以涉嫌扰乱公共秩序罪刑事立案调查。</p><p>一个律师，依据《立法法》赋予公民的立法建议权，向最高立法机关提出专业意见——这一行为本身被逐步升级为&quot;违规&quot;→&quot;行政处罚&quot;→&quot;刑事追责&quot;。而用来完成这一升级的法律工具，恰恰是那些构成要件模糊、边界不清的&quot;口袋&quot;条款。</p><p><strong>这不是假设，不是推演，而是正在发生的现实：模糊的规则不仅没有保护于凯，反而成了碾碎他的工具。</strong></p><h3 id="非法经营罪-另一个-口袋-的扩张史" tabindex="-1">非法经营罪：另一个&quot;口袋&quot;的扩张史 <a class="header-anchor" href="#非法经营罪-另一个-口袋-的扩张史" aria-label="Permalink to &quot;非法经营罪：另一个&quot;口袋&quot;的扩张史&quot;">​</a></h3><p>与寻衅滋事罪并行的，是非法经营罪的持续扩张。该罪源自1979年《刑法》中的投机倒把罪，1997年《刑法》将其分解后，第225条第4项&quot;其他严重扰乱市场秩序的非法经营行为&quot;这一兜底条款，使其成为另一个典型的&quot;口袋罪&quot;。</p><p>最高人民法院2016年再审的王力军案即为典型：内蒙古巴彦淖尔农民王力军无证收购玉米，一审被判非法经营罪，最终最高人民法院指令再审改判无罪，明确指出&quot;对于虽然违反行政管理有关规定，但尚未严重扰乱市场秩序的经营行为，不应当认定为非法经营罪&quot;。</p><p>法学界对口袋罪的理论批判早已形成共识。有学者从刑法明确性角度指出：&quot;含糊的刑法无异于否定罪刑法定和否定刑法的自由价值。对于国家来说，一部不确定或含糊的刑法，不能保护民众免受专制的压迫，它不仅违反分权原理、允许法官随意解释而替代立法，而且不能为国家的刑罚权提供自我限制的约束。&quot;</p><h3 id="必要的区分-本文反对的是什么-模糊" tabindex="-1">必要的区分：本文反对的是什么&quot;模糊&quot; <a class="header-anchor" href="#必要的区分-本文反对的是什么-模糊" aria-label="Permalink to &quot;必要的区分：本文反对的是什么&quot;模糊&quot;&quot;">​</a></h3><p>在继续论述之前，必须做一个关键的概念澄清，否则读者可能误以为本文反对一切形式的司法裁量空间。</p><p><strong>本文批判的&quot;模糊&quot;，特指立法层面的模糊——即法律条文本身使用了&quot;其他&quot;&quot;情节恶劣&quot;&quot;严重扰乱&quot;等缺乏明确客观判断标准的兜底性表述，使得&quot;什么行为构成犯罪&quot;的决定权从立法机关转移给了执法者和法官。</strong> 寻衅滋事罪中的&quot;随意殴打他人，情节恶劣的&quot;、非法经营罪中的&quot;其他严重扰乱市场秩序的非法经营行为&quot;，都属于这一类。</p><p><strong>本文并不反对在明确的构成要件框架内，法官根据具体案件情节在法定量刑幅度内进行裁量。</strong> 这种裁量空间是任何法律体系都不可或缺的——因为立法者不可能预见所有具体情形，司法者需要一定的弹性来实现个案正义。赵春华案最终推动的&quot;不唯数值论&quot;改革，本质上就是在明确的犯罪构成框架内引入更精细的情节考量，这恰恰是合理裁量空间的体现。</p><p><strong>关键区别在于：合理裁量空间是在&quot;明确的构成要件&quot;之下运作的，它解决的是&quot;判多重&quot;的问题；而本文批判的立法模糊，是在&quot;是否构成犯罪&quot;这个最根本的问题上放弃了明确性，它解决的是&quot;算不算犯罪&quot;的问题。前者是法治的弹性，后者是法治的溃堤。</strong></p><h3 id="案例精确化-模糊性可以被驯服-但前提是机制在场" tabindex="-1">案例精确化：模糊性可以被驯服，但前提是机制在场 <a class="header-anchor" href="#案例精确化-模糊性可以被驯服-但前提是机制在场" aria-label="Permalink to &quot;案例精确化：模糊性可以被驯服，但前提是机制在场&quot;">​</a></h3><p>但仅仅做上述区分还不够。还需要进一步追问：即便在立法层面存在一定程度的模糊性，是否存在一套有效的机制来逐步精确化这些边界？</p><p>答案是：在成熟的法治体系中，这种机制是存在的。它的名字叫<strong>案例制度</strong>。当成文法的条文无法覆盖新的社会情形时，法院通过一个个具体案件的裁判，逐步精确化法律的适用边界。每一个判决都在回答一个具体问题：这个条文在这个情形下到底适不适用？适用到什么程度？这些判决积累起来，就形成了一套比条文本身更精细的边界地图。普通法系的判例制度是这种机制的典型形态，但大陆法系同样通过最高法院的指导性案例、公报案例等机制发挥着类似的功能。</p><p>在这种机制下，立法层面的模糊性不是致命的——因为司法系统有能力通过案例不断去精确地界定它。模糊性变成了一个&quot;待填充的框架&quot;，而不是一个&quot;永远敞开的后门&quot;。</p><p><strong>但问题在于：这套机制要有效运转，有一个不可替代的前提——司法必须拥有通过裁判精确界定边界的独立空间。</strong> 如果法官不敢判、不能判、判了也不算数，如果案例不具有任何约束力，如果每一次精确化边界的尝试都可能被行政权力推翻——那么模糊性就无法通过案例被逐步消除，它就只能一直敞开着，等待权力来填充。</p><p><strong>这正是本文批判的核心所在：问题不在于法律条文存在模糊性——这在任何法律体系中都不可避免——而在于当模糊性出现时，是否存在有效的机制来逐步精确化它。如果这套机制缺位，模糊性就从&quot;立法的技术局限&quot;变成了&quot;权力扩张的结构性后门&quot;。</strong></p><h3 id="四、法理学的底层逻辑-为什么-明确-是法治的命脉" tabindex="-1">四、法理学的底层逻辑：为什么&quot;明确&quot;是法治的命脉 <a class="header-anchor" href="#四、法理学的底层逻辑-为什么-明确-是法治的命脉" aria-label="Permalink to &quot;四、法理学的底层逻辑：为什么&quot;明确&quot;是法治的命脉&quot;">​</a></h3><h3 id="贝卡里亚-法律含混性是专制的温床" tabindex="-1">贝卡里亚：法律含混性是专制的温床 <a class="header-anchor" href="#贝卡里亚-法律含混性是专制的温床" aria-label="Permalink to &quot;贝卡里亚：法律含混性是专制的温床&quot;">​</a></h3><p>早在1764年，意大利法学家贝卡里亚在其传世之作《论犯罪与刑罚》中就系统论述了法律明确性的极端重要性。他指出：&quot;尤其糟糕的是，法律是用一种人民所不了解的语言写成的，这就使人民处于对少数法律解释者的依赖地位，而无从掌握自己的自由，或处置自己的命运。&quot;贝卡里亚主张运用几何学原理构建一个精确、普遍的犯罪与刑罚的阶梯，以防止司法专横。</p><h3 id="孟德斯鸠-模糊法律是专制政体的标志" tabindex="-1">孟德斯鸠：模糊法律是专制政体的标志 <a class="header-anchor" href="#孟德斯鸠-模糊法律是专制政体的标志" aria-label="Permalink to &quot;孟德斯鸠：模糊法律是专制政体的标志&quot;">​</a></h3><p>孟德斯鸠在《论法的精神》中从政体角度分析了法律明确性问题。他尖锐地指出：&quot;当一个人使自己拥有绝对权力时，首先想到的就是简化法律&quot;&quot;专制国家里什么法律都没有，法官本身就是法规。&quot;而在共和国里，&quot;政体的性质要求法官一丝不苟地依照法律的字面含义判案&quot;。换言之，<strong>法律的模糊程度与政体的专制程度成正比</strong>——这不是现代法学家的推演，而是启蒙思想家两百多年前的定论。</p><h3 id="富勒-法律的-内在道德-与明确性" tabindex="-1">富勒：法律的&quot;内在道德&quot;与明确性 <a class="header-anchor" href="#富勒-法律的-内在道德-与明确性" aria-label="Permalink to &quot;富勒：法律的&quot;内在道德&quot;与明确性&quot;">​</a></h3><p>20世纪法哲学的核心论争之一——哈特与富勒论战——进一步将法律明确性提升到&quot;法律之所以为法律&quot;的本体论高度。美国法学家朗·富勒在《法律的道德性》（1964）中提出法律必须具备八项&quot;内在道德&quot;原则，其中第四项即为&quot;法律规则必须明确，能够被人理解&quot;。富勒认为，全然无视这些原则所产生的不仅是恶法，<strong>确切地说，它根本就不是法律</strong>。</p><h3 id="霍布斯-即便是绝对主权论者也要求法律明确" tabindex="-1">霍布斯：即便是绝对主权论者也要求法律明确 <a class="header-anchor" href="#霍布斯-即便是绝对主权论者也要求法律明确" aria-label="Permalink to &quot;霍布斯：即便是绝对主权论者也要求法律明确&quot;">​</a></h3><p>即便是被视为绝对主义代表的霍布斯，在《利维坦》中也明确将&quot;使臣民知悉其权利与义务&quot;列为主权者的核心职责之一，强调&quot;通过清晰、成文的法律让臣民明确&#39;我的&#39;和&#39;你的&#39;之分，法律的模糊是对人民的伤害&quot;。霍布斯还要求主权者&quot;制定良好的法律：法律应为人民的利益所需且明确清晰，其目的在于引导而非绊倒人民&quot;。</p><h3 id="罪刑法定原则-明确性是基石" tabindex="-1">罪刑法定原则：明确性是基石 <a class="header-anchor" href="#罪刑法定原则-明确性是基石" aria-label="Permalink to &quot;罪刑法定原则：明确性是基石&quot;">​</a></h3><p>上述思想传统汇聚为现代刑法的核心原则——罪刑法定原则（<em>nullum crimen, nulla poena sine lege</em>）。该原则要求&quot;法无明文规定不为罪，法无明文规定不处罚&quot;，而明确性是其最基本的要求之一。正如学者所言：&quot;明确性是罪刑法定原则的根本保障，如果没有刑事立法的明确性，那么罪刑法定根本无法实现。&quot;</p><p>1791年《法国刑法典》就是早期对明确性追求的极端实践——对各种犯罪都规定了具体的构成要件和绝对确定的法定刑，其目的在于排除法官的自由裁量权，防止司法专横，保障公民的权利和自由。</p><p><strong>从贝卡里亚到富勒，从孟德斯鸠到霍布斯，跨越两百余年、横跨不同政治立场的思想家，在一个问题上达成了罕见的一致：法律的明确性是自由的保障，法律的模糊性是专制的温床。</strong> 那些呼吁&quot;法律模糊点更好&quot;的人，实际上是在与整个现代法治文明的基本共识为敌。</p><h3 id="五、-程序正义让坏人跑了-对实质正义的原始执念" tabindex="-1">五、&quot;程序正义让坏人跑了&quot;：对实质正义的原始执念 <a class="header-anchor" href="#五、-程序正义让坏人跑了-对实质正义的原始执念" aria-label="Permalink to &quot;五、&quot;程序正义让坏人跑了&quot;：对实质正义的原始执念&quot;">​</a></h3><p>第二种常见的替权力辩护的逻辑是：<strong>&quot;你看，程序正义搞得太复杂了，坏人钻空子跑了，受害者反而得不到公道。要是别搞那么多程序，直接抓了判了，多痛快。&quot;</strong></p><p>这种想法的心理学根源极其古老——它来自人类对&quot;报应正义&quot;的原始执念。在人类的进化史上，&quot;以眼还眼&quot;的即时报应比&quot;走完程序再报应&quot;更能带来心理满足。程序正义是一种晚近的制度发明，它违反直觉，需要教育才能理解。而&quot;实质正义&quot;——坏人必须被惩罚，不管用什么手段——才是人类大脑的默认设置。</p><p>但人们忘记了1997年《刑法》修订和1996年《刑事诉讼法》修改的历史背景：正是流氓罪时代&quot;重口供轻证据&quot;&quot;疑罪从有&quot;的司法顽疾，以及1983年&quot;严打&quot;中大量冤假错案的惨痛教训，才催生了&quot;疑罪从无&quot;原则的确立和程序正义理念的引入。这是用无数人的命运换来的法治觉醒。</p><p>你今天觉得&quot;程序太复杂让坏人跑了&quot;，明天你就可能成为那个&quot;因为程序太简单而被冤枉的好人&quot;。当程序被简化到&quot;直接抓了判了&quot;的程度，第一个被碾碎的往往不是真正的坏人——因为真正的坏人有资源、有关系、有能力规避风险——而是没有资源、没有关系、没有能力的普通人。</p><p>于凯案就是最鲜活的注脚：一个依法行使立法建议权的专业律师，被一步步从&quot;提建议&quot;升级到&quot;刑事追责&quot;——这个过程中，恰恰是程序正义的缺位，才使得这种升级成为可能。</p><h3 id="六、-目的不纯就该管-动机审查的致命诱惑" tabindex="-1">六、&quot;目的不纯就该管&quot;：动机审查的致命诱惑 <a class="header-anchor" href="#六、-目的不纯就该管-动机审查的致命诱惑" aria-label="Permalink to &quot;六、&quot;目的不纯就该管&quot;：动机审查的致命诱惑&quot;">​</a></h3><p>第三种替权力辩护的逻辑，也是最危险的一种：<strong>&quot;有些人目的不纯，但又抓不住什么把柄，这样也不行啊。&quot;&quot;核心还是要判断说话的目的，是拯救别人还是想贬损别人。&quot;</strong></p><p>这句话翻译成法律语言就是：<strong>应当根据说话者的&quot;目的&quot;而非&quot;行为&quot;来判断合法性。</strong></p><h3 id="主观归罪-刑法学早已警惕的陷阱" tabindex="-1">主观归罪：刑法学早已警惕的陷阱 <a class="header-anchor" href="#主观归罪-刑法学早已警惕的陷阱" aria-label="Permalink to &quot;主观归罪：刑法学早已警惕的陷阱&quot;">​</a></h3><p>中国刑法学界对&quot;主观归罪&quot;的警惕由来已久。所谓主观归罪，是指以行为人的主观心理态度为核心判断依据，而忽视行为本身的客观属性，只要行为人具有犯罪故意或过失，就认定其行为构成犯罪，即便其行为客观上并未造成危害结果。有学者明确指出，这种逻辑&quot;会导致司法机关过度关注行为人的主观想法，而忽视对客观行为的实质性审查，进而使得公民的正当行为面临被怀疑、被定罪的风险，严重违背了刑法的人权保障功能&quot;。</p><p>在寻衅滋事罪的司法实践中，&quot;流氓动机&quot;的认定已经成为主观归罪的典型场域。华东政法大学魏昌东教授揭示，司法解释原本要求&quot;寻求刺激、发泄情绪、逞强耍横等无事生非&quot;作为主观要素，但在实践中被虚化，&quot;具有限缩刑法不当适用的&#39;寻求刺激&#39;要素被抛弃，&#39;逞强耍横&#39;成为唯一判断标准&quot;。北京大学陈兴良教授更直言，&quot;探究行为人的内心动机在司法实践中极为困难，且容易导致主观归罪。同样的殴打行为，因被认定动机不同，可能面临治安处罚、寻衅滋事罪或故意伤害罪等截然不同的法律评价，这严重损害了法律适用的统一性和公正性。&quot;</p><h3 id="动机审查的实践后果" tabindex="-1">动机审查的实践后果 <a class="header-anchor" href="#动机审查的实践后果" aria-label="Permalink to &quot;动机审查的实践后果&quot;">​</a></h3><p>一旦&quot;目的审查&quot;成为合法性判断的标准，意味着什么？意味着你说了什么不重要，<strong>权力机关认为你为什么说才重要</strong>。你揭露腐败，可以被解释为&quot;动机不纯&quot;；你批评政策，可以被解释为&quot;别有用心&quot;；你转发了什么内容，可以被解释为&quot;配合境外势力&quot;。这不是假设，是近年来大量公共事件中反复出现的标准话术。</p><p>为什么那么多人主动拥抱&quot;动机审查&quot;？因为<strong>动机审查提供了一种极其廉价的心理满足感</strong>：我不需要理解你说了什么，我只需要判定你&quot;居心何在&quot;，就可以否定你的全部表达。这是一种认知上的偷懒——你不需要费力气去理解一个复杂的论证，只需要给它贴上一个&quot;动机不纯&quot;的标签，就可以心安理得地忽略它。</p><p>更深层的原因是：<strong>动机审查给了普通人一种&quot;我也能参与审判&quot;的幻觉。</strong> 在行为审查的框架下，判断一个人是否违法需要专业知识、需要证据、需要程序——普通人没有这个能力。但在动机审查的框架下，任何人都可以充当&quot;动机鉴定师&quot;：我觉得你目的不纯，你就是目的不纯。这种&quot;人人皆可审判&quot;的幻觉，让普通人觉得自己也是权力结构的一部分，而不是被权力审判的对象。</p><p><strong>这是一种致命的身份错位。你以为你在替权力行使审判权，但权力随时可以把审判的矛头转向你——而审判你的标准，正是你亲手拥护的&quot;动机审查&quot;。</strong></p><h3 id="七、-发动群众判案就好了-法治最古老的敌人" tabindex="-1">七、&quot;发动群众判案就好了&quot;：法治最古老的敌人 <a class="header-anchor" href="#七、-发动群众判案就好了-法治最古老的敌人" aria-label="Permalink to &quot;七、&quot;发动群众判案就好了&quot;：法治最古老的敌人&quot;">​</a></h3><p>还有一种替权力辩护的逻辑，比前面所有陷阱都更古老、更隐蔽、也更具迷惑性：<strong>&quot;法律没必要写得那么明确，发动群众起来判案不就好了？群众的眼睛是雪亮的，公道自在人心。&quot;</strong></p><p>这个说法听起来极其朴素、极其民主、极其&quot;接地气&quot;。它诉诸一种深植于中国文化中的信念：法律是精英的东西，而正义是人民的东西；当法律脱离了人民的直觉，那就应该让人民自己来裁判。</p><p><strong>但这个逻辑犯了一个致命的错误：它把&quot;正义感&quot;等同于&quot;正义&quot;。</strong></p><p>群众的眼睛确实是雪亮的——但雪亮的眼睛不等于精确的尺度。一个人看到邻居偷东西，他的愤怒是真实的、正当的；但他的愤怒不能替代&quot;偷了多少&quot;&quot;是否构成犯罪&quot;&quot;应当判处什么刑罚&quot;这些需要专业判断的问题。正义感是一种情感反应，正义是一套制度安排。前者是后者的动力来源之一，但绝不是后者的替代品。</p><p>而中国自己的历史，已经用最惨烈的方式证明过这一点。</p><h3 id="六七十年代-一场持续十年的-群众判案-实验" tabindex="-1">六七十年代：一场持续十年的&quot;群众判案&quot;实验 <a class="header-anchor" href="#六七十年代-一场持续十年的-群众判案-实验" aria-label="Permalink to &quot;六七十年代：一场持续十年的&quot;群众判案&quot;实验&quot;">​</a></h3><p>如果说&quot;发动群众判案&quot;只是一个理论假设，那我们可以争论它的利弊。但它不是一个假设。<strong>它是1966年至1976年间在中国大地上完整运行了十年的制度实践。</strong></p><p>这十年里，公检法被彻底砸烂。1967年1月，中共中央发布《关于在无产阶级文化大革命中加强公安工作的若干规定》（即&quot;公安六条&quot;），将&quot;攻击污蔑伟大领袖毛主席和他的亲密战友林彪同志&quot;定为&quot;现行反革命行为&quot;，同时规定&quot;凡是投寄反革命匿名信、秘密或公开张贴、散发反革命传单、写反动标语、喊反动口号，以攻击污蔑伟大领袖毛主席和他的亲密战友林彪同志的，都是现行反革命分子，应当依法惩办&quot;。这份文件没有经过任何立法程序，没有明确的构成要件，没有证据标准，没有上诉机制——它本身就是一份&quot;模糊规则&quot;的极端样本，而它的执行方式，就是&quot;发动群众&quot;。</p><p>于是，&quot;群众判案&quot;从口号变成了日常。工厂里开批斗会，由工友决定谁是&quot;阶级敌人&quot;；农村里开斗争大会，由社员决定谁该被抄家、游街、关进牛棚；学校里红卫兵自行设立&quot;审讯室&quot;，对被怀疑&quot;思想有问题&quot;的教师和同学实施体罚乃至殴打致死。北京大兴县1966年8月至9月的&quot;红八月&quot;期间，仅一个县就有325名&quot;四类分子&quot;及其家属被群众打死，最小的死者年仅38天。湖南道县1967年的&quot;道县事件&quot;中，4519人在&quot;贫下中农最高人民法院&quot;的名义下被杀害，其中包括大量老人、妇女和儿童。广西多地出现了大规模的&quot;群众专政&quot;杀人事件，仅武鸣一县就有超过1500人遇害。</p><p>这些杀戮不是暗中进行的不为人知的罪行。它们是在&quot;群众路线&quot;&quot;人民当家作主&quot;&quot;打破资产阶级法权&quot;的旗帜下公开进行的。参与者不是职业刽子手，而是普通的工人、农民、学生、干部——他们真心相信自己在&quot;保卫毛主席的革命路线&quot;，相信自己是在&quot;执行人民的意志&quot;。</p><p><strong>这就是&quot;发动群众判案&quot;的真实面貌：没有程序，没有证据，没有辩护，没有上诉，没有追责。裁判的标准是当下多数人的情绪，裁判的主体是一个无法被问责的集体，裁判的结果是不可逆转的死亡。</strong></p><p>而那些被&quot;群众&quot;判定为&quot;坏人&quot;的人，他们的罪名是什么？是&quot;家庭出身不好&quot;，是&quot;说过一句不合时宜的话&quot;，是&quot;被人举报态度不端正&quot;，是&quot;历史上曾经参加过国民党&quot;——所有这些&quot;罪名&quot;都没有经过任何法律程序的审查，没有任何客观标准的检验，仅仅因为在特定的政治氛围下，它们足以激发群众的愤怒。</p><p><strong>&quot;群众的眼睛是雪亮的&quot;吗？在那十年里，雪亮的眼睛看到了无数&quot;敌人&quot;，但没有看到一个无辜者。</strong></p><h3 id="群众判案-的三个结构性缺陷" tabindex="-1">&quot;群众判案&quot;的三个结构性缺陷 <a class="header-anchor" href="#群众判案-的三个结构性缺陷" aria-label="Permalink to &quot;&quot;群众判案&quot;的三个结构性缺陷&quot;">​</a></h3><p>六七十年代的经验不是偶然的失控，而是&quot;群众判案&quot;这一模式内在缺陷的必然展开。它暴露了三个无法克服的结构性问题：</p><p><strong>第一，多数人的暴政没有刹车机制。</strong> 群众判案没有程序保障，没有证据规则，没有上诉机制。它的裁判标准只有一个：当下多数人的情绪。而情绪是最容易被操纵、最容易被煽动、也最容易出错的东西。当一千个人在批斗会上齐声高呼&quot;打倒&quot;的时候，没有任何制度力量能够按下暂停键，问一句&quot;证据呢？&quot;那些被当场宣判、当场执行的人中，有多少是经过严格证据审查的？有多少只是因为&quot;看起来像坏人&quot;就被集体的愤怒吞噬了？群众判案的逻辑下，&quot;少数人&quot;永远是最先被牺牲的——因为他们的权利没有任何制度屏障来抵御多数人的情绪。</p><p><strong>第二，责任的彻底消失。</strong> 法律之所以要由专业的法官来适用，一个核心原因是：法官必须为自己的判决承担职业责任。判决书上写着他的名字，上诉法院可以推翻他的裁判，错案追究制可以追溯他的过失。但&quot;群众&quot;是一个没有面孔、没有名字、无法被追责的主体。当一千个人共同喊出&quot;该杀&quot;的时候，谁来为这个决定负责？没有人。每个人都觉得自己只是&quot;表达了意见&quot;，没有人觉得自己在&quot;做出判决&quot;。文革结束后，大量冤假错案得到平反，但当年参与批斗、参与抄家、参与暴力的人，几乎没有人受到法律追究——不是因为赦免，而是因为根本无法确定&quot;谁该负责&quot;。这种集体无责任状态，是制造冤案最完美的温床——因为没有任何人为后果买单。</p><p><strong>第三，权力对&quot;民意&quot;的完美征用。</strong> 这是最致命的一点。&quot;发动群众判案&quot;表面上是把裁判权交给人民，实际上是把裁判权交给了<strong>那个有能力定义&quot;群众意志&quot;的人</strong>。谁来组织批斗会？谁来设定&quot;斗争对象&quot;？谁来汇总&quot;群众意见&quot;？谁来决定哪些声音算&quot;革命群众的声音&quot;、哪些声音算&quot;阶级敌人的反扑&quot;？答案永远是当时的权力掌控者。&quot;公安六条&quot;本身就是最好的例证：它以&quot;保护伟大领袖&quot;为名，把打击范围无限扩大，而执行的工具恰恰是&quot;发动群众&quot;。群众以为自己在行使权力，实际上只是权力的传声筒和执行器。</p><p><strong>&quot;发动群众判案&quot;从来不是权力的对立面，而是权力最精致的伪装。</strong> 它让权力的扩张获得了&quot;民主&quot;的外衣，让受害者连申诉的对象都找不到——因为你不能起诉&quot;群众&quot;，你不能上诉&quot;民意&quot;，你甚至不能说&quot;群众错了&quot;，因为那等于说&quot;人民错了&quot;。</p><h3 id="为什么这段历史不能被遗忘" tabindex="-1">为什么这段历史不能被遗忘 <a class="header-anchor" href="#为什么这段历史不能被遗忘" aria-label="Permalink to &quot;为什么这段历史不能被遗忘&quot;">​</a></h3><p>有人可能会说：&quot;那是特殊年代的事，现在不一样了。&quot;</p><p>是的，现在确实不一样了。公检法恢复了，刑法制定了，刑事诉讼法修改了，&quot;疑罪从无&quot;写进了条文。但&quot;发动群众判案&quot;的思维并没有随着制度的重建而自动消失。它仍然潜伏在许多人的认知深处，每当出现一个引发公众愤怒的案件，它就会以新的面目重新浮现：&quot;这种人就该枪毙&quot;&quot;别跟他讲什么程序&quot;&quot;网民都说他有罪他还跑得了？&quot;&quot;舆论都这样了法院还不判？&quot;</p><p>这些话术和六七十年代的批斗口号在形式上不同，但在结构上完全相同：<strong>用情绪替代证据，用多数人的声音替代程序，用不可追责的&quot;民意&quot;替代可追责的制度。</strong></p><p>政治哲学家乔恩·埃尔斯特在《尤利西斯与塞壬》（又译《宪政与民主》）中用一个古老的隐喻精确地描述了这种张力：奥德修斯知道自己听到塞壬歌声时会丧失理智、驾船触礁，所以他在清醒时命令水手把自己绑在桅杆上，并嘱咐水手无论他如何哀求都不要松绑。<strong>宪政就是这根绳子——它不是对民主的否定，而是民主在清醒时对自己的预先约束。</strong> 民主是船上的水手，是航行的动力来源；但如果没有那根绳子，水手的热情就会把船引向礁石。六七十年代的悲剧，恰恰是一个民族在&quot;听到塞壬歌声&quot;的时刻，不仅解开了绳子，还把绑绳子的人当成了敌人。</p><p>这就是为什么我们必须反复回到这段历史。不是为了控诉，不是为了清算，而是因为：<strong>这段历史是中国法治建设最昂贵的学费，也是我们对&quot;绳子&quot;之必要性的最惨痛验证。</strong> 它是用数千万人的命运换来的教训——这个教训的核心内容是：正义不能靠感觉，只能靠制度；裁判权不能交给情绪，只能交给程序；&quot;群众&quot;可以是正义的动力，但绝不能是正义的尺度。</p><p><strong>&quot;群众的眼睛是雪亮的&quot;这句话本身没错。但雪亮的眼睛需要一把精确的尺子，才能量出正义的长度。没有尺子的眼睛，看到的不是正义，只是自己的倒影。</strong></p><p>而六七十年代的那十年，就是一面没有尺子的镜子。它照出的不是正义，而是一个民族在失去制度约束之后，能够对自己施加怎样的暴力。</p><p><strong>这面镜子不能碎。碎了，我们就忘了自己曾经站在深渊边上。而那根绳子，也不能松。松了，塞壬的歌声就会再次听起来像正义本身。</strong></p><h3 id="八、-青天大老爷-的文化基因-人治传统的深层编码" tabindex="-1">八、&quot;青天大老爷&quot;的文化基因：人治传统的深层编码 <a class="header-anchor" href="#八、-青天大老爷-的文化基因-人治传统的深层编码" aria-label="Permalink to &quot;八、&quot;青天大老爷&quot;的文化基因：人治传统的深层编码&quot;">​</a></h3><p>以上所有认知陷阱之所以如此顽固，是因为它们背后有一套更深层的文化基因在支撑——<strong>人治传统的深层编码</strong>。</p><p>中国两千年的帝制传统，塑造了一种根深蒂固的政治想象：<strong>好的治理不靠规则，靠&quot;青天大老爷&quot;。</strong> 包拯、海瑞、狄仁杰——这些民间叙事中的英雄，无一例外都是&quot;不拘泥于法律条文、凭良心断案&quot;的清官。在这种文化编码中，&quot;规则&quot;是冷的、死的、不近人情的，而&quot;青天&quot;是热的、活的、能体察民情的。</p><p>这种文化编码至今仍在运作。你会发现，很多人在批评某个具体执法行为的同时，仍然相信&quot;上面是好的&quot;&quot;中央是好的&quot;&quot;只要上面知道了就会解决&quot;。他们把希望寄托在&quot;更高层级的权力&quot;上，而不是寄托在&quot;约束所有层级权力的规则&quot;上。</p><p>这就是为什么那么多人会觉得&quot;模糊规则更好&quot;——因为模糊规则意味着&quot;上面&quot;有更大的裁量空间，可以根据&quot;实际情况&quot;灵活处理，可以&quot;特事特办&quot;，可以&quot;急事急办&quot;。在他们看来，这是一种&quot;有人情味&quot;的治理方式。</p><p>但他们不知道的是：<strong>&quot;有人情味&quot;的治理，本质上就是&quot;看人下菜碟&quot;的治理。</strong> 今天&quot;上面&quot;觉得你值得同情，就灵活处理；明天&quot;上面&quot;觉得你碍事，就严格执法。你的一切权利，都取决于&quot;上面&quot;的心情，而不是你自己的资格。</p><p>赵春华案二审改判缓刑，是&quot;有人情味&quot;的体现。但同一天，还有无数个&quot;赵春华&quot;没有得到&quot;灵活处理&quot;——他们的命运取决于法官当天的心情、领导的批示、舆论的热度，而不是法律本身。<strong>这种&quot;看人下菜碟&quot;的治理，正是法治要消灭的东西。</strong></p><p><strong>人治的&quot;人情味&quot;，是权力的施舍；法治的&quot;冷冰冰&quot;，才是权利的保障。</strong> 但人类总是更容易被&quot;施舍的温暖&quot;打动，而不是被&quot;保障的冷漠&quot;说服。这是人性的弱点，也是人治传统最顽固的生命力所在。</p><h3 id="九、权力的-借力打力-民间辩护如何被系统性征用" tabindex="-1">九、权力的&quot;借力打力&quot;：民间辩护如何被系统性征用 <a class="header-anchor" href="#九、权力的-借力打力-民间辩护如何被系统性征用" aria-label="Permalink to &quot;九、权力的&quot;借力打力&quot;：民间辩护如何被系统性征用&quot;">​</a></h3><h3 id="权力-的具体拆解" tabindex="-1">&quot;权力&quot;的具体拆解 <a class="header-anchor" href="#权力-的具体拆解" aria-label="Permalink to &quot;&quot;权力&quot;的具体拆解&quot;">​</a></h3><p>在进入机制分析之前，需要对&quot;权力&quot;一词做必要的去神秘化处理。本文所说的&quot;权力&quot;不是一个铁板一块的抽象实体，而是由不同层级、不同部门构成的复合结构：</p><ul><li><strong>立法权</strong>：制定法律规则，决定&quot;什么行为构成犯罪&quot;的边界；</li><li><strong>行政权</strong>：通过部门规章、规范性文件等，在立法框架内细化执行标准（如公安部的1.8焦耳标准）；</li><li><strong>司法权</strong>：通过司法解释和个案裁判，进一步明确或模糊法律的适用边界；</li><li><strong>执法权</strong>：在具体案件中行使自由裁量权，决定&quot;抓不抓&quot;&quot;怎么抓&quot;&quot;抓到什么程度&quot;。</li></ul><p>本文所讨论的&quot;模糊规则&quot;问题，核心发生在<strong>立法权和行政权</strong>层面——即&quot;什么行为构成犯罪&quot;的边界本身不够明确。而&quot;借力打力&quot;的征用机制，则主要发生在<strong>执法权和司法权</strong>层面——即当舆论呼吁&quot;从严打击&quot;时，执法机关获得了更大的裁量空间，司法机关获得了更宽松的裁判环境。</p><p>需要指出的是，权力内部并非铁板一块。立法机关、司法机关、行政机关之间存在张力，不同部门之间也存在博弈。但本文关注的不是权力内部的博弈过程，而是<strong>当民间舆论指向&quot;拆锁&quot;方向时，这套制度激励结构的客观效果</strong>——无论权力内部有多少分歧，&quot;从严打击&quot;的舆论压力总是更容易被转化为扩权行动，而&quot;保障权利&quot;的舆论压力则往往被消解在漫长的程序之中。</p><h3 id="四步循环机制" tabindex="-1">四步循环机制 <a class="header-anchor" href="#四步循环机制" aria-label="Permalink to &quot;四步循环机制&quot;">​</a></h3><p><strong>第一步：制造一个引发公众愤怒的具体事件。</strong> 比如一个&quot;坏人&quot;因为程序问题被释放，比如一个&quot;普通人&quot;因为&quot;规则太明确&quot;被判重刑。</p><p><strong>第二步：引导舆论将愤怒指向&quot;规则&quot;而非&quot;权力&quot;。</strong> 不是&quot;公安部定的标准不合理&quot;，而是&quot;法律太明确了&quot;；不是&quot;执法者滥用自由裁量权&quot;，而是&quot;程序太复杂了&quot;；不是&quot;权力不受约束&quot;，而是&quot;有些人目的不纯&quot;。</p><p><strong>第三步：借舆论之力，进一步压缩规则、扩大裁量。</strong> 每一次公众对&quot;规则&quot;的愤怒，都被转化为&quot;规则需要修改&quot;的民意基础。而&quot;修改&quot;的方向，永远是给权力留更大的空间。</p><p><strong>第四步：循环。</strong> 更大的裁量空间导致更大的荒谬，更大的荒谬引发更大的愤怒，更大的愤怒被引导向&quot;规则需要再修改&quot;……</p><p>这个循环在口袋罪的扩张史中表现得淋漓尽致。1997年废除流氓罪，拆解为寻衅滋事罪等具体罪名，本意是限缩处罚范围。但寻衅滋事罪继承了流氓罪的&quot;口袋基因&quot;，在司法解释的推动下不断扩张。2013年两高司法解释试图以&quot;无事生非&quot;的主观动机限定适用范围，但在实践中被虚化。最高人民法院2023年的调研报告终于承认了寻衅滋事罪&quot;口袋化趋重&quot;的问题，但对&quot;因边界不清导致容易被泛化适用&quot;的行为类型究竟有哪些，仍未给出明确回答。</p><p>而每一次&quot;口袋化&quot;的扩张，都伴随着民间舆论的&quot;自愿配合&quot;——&quot;这种人就该抓&quot;&quot;法律太宽松了&quot;&quot;程序太多余了&quot;。权力几乎不需要亲自下场，只需要<strong>引导归因方向</strong>——把公众的愤怒从&quot;权力不受约束&quot;引导到&quot;规则本身有问题&quot;——就能借力打力，让普通人主动替它拆掉约束自己的笼子。</p><p><strong>而每一次&quot;拆笼&quot;，都有民间舆论的&quot;自愿配合&quot;。</strong> 这才是最讽刺的地方：权力的扩张不是靠强制力完成的，而是靠被统治者主动交出自由完成的。</p><h3 id="十、-反正改不了-的习得性无助-最隐蔽的帮凶" tabindex="-1">十、&quot;反正改不了&quot;的习得性无助：最隐蔽的帮凶 <a class="header-anchor" href="#十、-反正改不了-的习得性无助-最隐蔽的帮凶" aria-label="Permalink to &quot;十、&quot;反正改不了&quot;的习得性无助：最隐蔽的帮凶&quot;">​</a></h3><p>还有一种更隐蔽的替权力辩护的方式，它不以&quot;积极辩护&quot;的面目出现，而是以&quot;消极放弃&quot;的面目出现：<strong>&quot;反正改不了&quot;&quot;说了也没用&quot;&quot;你以为你能改变什么&quot;&quot;别较真了&quot;&quot;差不多得了&quot;。</strong></p><p>这种心态在心理学上叫&quot;习得性无助&quot;（learned helplessness）——当一个人反复经历&quot;努力无效&quot;后，他会放弃努力，并且开始为&quot;放弃&quot;寻找合理性：&quot;不是我不想改变，是改变不了，所以我选择不改变，这不是懦弱，是理性。&quot;</p><p>习得性无助是最隐蔽的帮凶。因为它不需要你做任何事，只需要你<strong>什么都不做</strong>——不发声、不较真、不追问、不反抗。而当你&quot;什么都不做&quot;时，权力的扩张就畅通无阻。</p><p>于凯案就是习得性无助的最佳催化剂：一个专业律师，依法提出立法建议，结果从行政处罚升级到刑事追责——这让无数普通人得出结论：&quot;连律师都这样了，我还能怎么办？&quot;而这种&quot;我还能怎么办&quot;的消极放弃，恰恰是权力最希望看到的。</p><p>更可怕的是，习得性无助会自我强化：你越是不行动，权力就越是扩张；权力越是扩张，你就越觉得&quot;果然改不了&quot;；你越觉得&quot;改不了&quot;，你就越不行动……</p><p><strong>最终，习得性无助完成了一个完美的闭环：它让你相信&quot;放弃是理性的&quot;，而你的放弃恰恰证明了权力的不可战胜——但这恰恰是因为你放弃了，权力才不可战胜。</strong></p><h2 id="下篇-纯良之恶——为什么-好心-比-恶意-更危险" tabindex="-1">下篇：纯良之恶——为什么&quot;好心&quot;比&quot;恶意&quot;更危险 <a class="header-anchor" href="#下篇-纯良之恶——为什么-好心-比-恶意-更危险" aria-label="Permalink to &quot;下篇：纯良之恶——为什么&quot;好心&quot;比&quot;恶意&quot;更危险&quot;">​</a></h2><h3 id="一、先理解他们的恐惧" tabindex="-1">一、先理解他们的恐惧 <a class="header-anchor" href="#一、先理解他们的恐惧" aria-label="Permalink to &quot;一、先理解他们的恐惧&quot;">​</a></h3><p>在进入论证之前，必须首先承认一个事实：<strong>那些呼吁&quot;把坏人抓起来&quot;的普通人，他们的恐惧是真实的。</strong></p><p>一个在治安混乱的街区生活了十年的母亲，她的孩子上学路上曾被小混混拦截勒索；一个做小生意的个体户，他的店铺曾被地痞反复骚扰，报警后却因&quot;不够立案标准&quot;而不了了之；一个独居的老人，她每天晚饭后不敢出门散步，因为巷子里的路灯坏了半年没人修。</p><p>这些人的恐惧不是虚构的，他们的焦虑不是&quot;被洗脑&quot;的结果。他们真心希望&quot;把坏人抓起来&quot;，不是因为他们邪恶，而是因为他们害怕。这种恐惧是人之常情，值得被尊重，而不是被嘲笑。</p><p><strong>但恐惧是真实的，不等于恐惧指向的政策方向是正确的。</strong></p><p>一个害怕火灾的人，他的恐惧是真实的。但如果他因此要求消防员&quot;不管三七二十一，看到冒烟就喷水&quot;，那他的恐惧就会制造比火灾更大的灾难——因为消防员会把水喷进无辜居民的家。问题不在于他的恐惧是假的，而在于他的恐惧指向了一个没有边界的解决方案。</p><p>同样，那些呼吁&quot;从重从快&quot;&quot;直接抓了算了&quot;&quot;别搞那么多程序&quot;的普通人，他们的安全焦虑是真实的。但他们要求的&quot;解决方案&quot;——简化程序、降低证据标准、扩大打击范围——恰恰是一个会反噬他们自己的方向。因为当程序被简化到&quot;直接抓了判了&quot;的程度，第一个被碾碎的往往不是真正的坏人，而是没有资源、没有关系、没有能力的普通人——恰恰是他们自己。</p><p><strong>本文的批判，从来不是指向他们的恐惧，而是指向恐惧所指向的方向。</strong></p><h3 id="二、一个令人不安的事实" tabindex="-1">二、一个令人不安的事实 <a class="header-anchor" href="#二、一个令人不安的事实" aria-label="Permalink to &quot;二、一个令人不安的事实&quot;">​</a></h3><p>在所有制造过巨大灾难的人当中，最危险的那一批，往往看起来纯良无害。</p><p>他们不贪财，不恋权，不谋私利。他们真心实意地相信自己在做正确的事——把坏人抓起来，让社会更干净，让好人不受欺负。他们甚至在道德上自我感动：我这么做不是为了自己，是为了大家。</p><p>但正是这种人，一次又一次地制造了人类历史上最深重的灾难。法国大革命时期的罗伯斯庇尔，被同时代人称为&quot;不可腐蚀者&quot;——他廉洁、自律、生活简朴、真心相信自己在缔造一个美德共和国。结果呢？他在14个月内将17000人送上了断头台。斯大林早年的战友、苏联检察官维辛斯基，在莫斯科审判中一手炮制了大量冤案，但他坚信自己在&quot;保卫社会主义祖国&quot;。中国1983年&quot;严打&quot;中的许多办案人员，真心相信自己在&quot;保护人民群众的生命财产安全&quot;——结果在&quot;从重从快&quot;的政策导向下，仅第一年全国就有2.4万人被判处死刑，大量无辜者被裹挟其中。</p><p>而真正出于私利作恶的人——贪官、骗子、黑社会——他们造成的伤害反而是有限的。因为他们有明确的利益边界：贪够了就走，骗完了就撤，他们的恶是有限的、可预测的、可防范的。</p><p><strong>真正可怕的，是那些没有利益边界的恶——因为他们的恶没有上限，而他们的良心又让他们相信这一切都是对的。</strong></p><h3 id="三、-把坏人抓起来-一个看似天经地义的逻辑如何通向深渊" tabindex="-1">三、&quot;把坏人抓起来&quot;：一个看似天经地义的逻辑如何通向深渊 <a class="header-anchor" href="#三、-把坏人抓起来-一个看似天经地义的逻辑如何通向深渊" aria-label="Permalink to &quot;三、&quot;把坏人抓起来&quot;：一个看似天经地义的逻辑如何通向深渊&quot;">​</a></h3><p>&quot;把坏人抓起来，社会就安全了&quot;——这个逻辑听起来无懈可击。谁不希望坏人受到惩罚？谁不希望好人得到保护？</p><p>但问题在于：<strong>谁来定义&quot;坏人&quot;？</strong></p><p>一旦你接受了&quot;把坏人抓起来&quot;这个前提，你就必须面对一个无法回避的问题：判断&quot;坏人&quot;的标准是什么？如果你说&quot;法律规定的就是坏人&quot;，那你至少还有一个客观的锚点——虽然这个锚点本身也可能有问题，但至少它是明确的、可质疑的、可修改的。</p><p>但&quot;追求结果正义&quot;的人往往不满足于法律标准。他们觉得&quot;法律太慢了&quot;&quot;法律太僵化了&quot;&quot;法律让坏人钻了空子&quot;。他们要的是&quot;实质正义&quot;——不管用什么手段，坏人必须受到惩罚。</p><p>一旦你接受了&quot;不管用什么手段&quot;这个前提，你就打开了一扇门：手段的边界消失了。今天你可以为了抓&quot;坏人&quot;而简化程序，明天你就可以为了抓&quot;坏人&quot;而降低证据标准，后天你就可以为了抓&quot;坏人&quot;而允许刑讯逼供。每一步都有&quot;正义&quot;的旗号，每一步都在缩小你的安全空间。</p><p>1983年&quot;严打&quot;就是这条逻辑链的完整演绎。起点是&quot;社会治安太差了，必须从重从快&quot;——这个起点本身并非没有合理性，文革结束后社会治安严重恶化是真实的。但一旦&quot;从重从快&quot;成为压倒一切的目标，程序正义就被系统性地抛弃了：公检法联合办案取代了相互制约，&quot;基本事实清楚、基本证据确凿&quot;的&quot;两个基本&quot;取代了&quot;事实清楚、证据确凿&quot;的证明标准，上诉期被压缩到三天，大量案件在&quot;速审速决&quot;中草率定案。最终，&quot;从重从快&quot;的逻辑不仅碾碎了无辜者，也没有真正解决治安问题——因为治安问题的根源是社会结构性的，不是多判几个人就能解决的。</p><p><strong>&quot;把坏人抓起来&quot;的逻辑之所以通向深渊，不是因为它的第一步错了，而是因为它的终点不受约束。当你把&quot;惩罚坏人&quot;设定为最高目标时，任何阻碍这个目标的东西——程序、证据、权利——都可以被牺牲。而当你牺牲完所有这些之后，你手里剩下的就不是正义，而是暴力。</strong></p><h3 id="四、为什么-纯良-比-自私-更危险-五个结构性原因" tabindex="-1">四、为什么&quot;纯良&quot;比&quot;自私&quot;更危险：五个结构性原因 <a class="header-anchor" href="#四、为什么-纯良-比-自私-更危险-五个结构性原因" aria-label="Permalink to &quot;四、为什么&quot;纯良&quot;比&quot;自私&quot;更危险：五个结构性原因&quot;">​</a></h3><h3 id="一-没有利益边界-就没有行为边界" tabindex="-1">（一）没有利益边界，就没有行为边界 <a class="header-anchor" href="#一-没有利益边界-就没有行为边界" aria-label="Permalink to &quot;（一）没有利益边界，就没有行为边界&quot;">​</a></h3><p>自私的人有上限。一个贪官贪够了就会收手，一个骗子骗完了就会消失，一个黑社会打完地盘就会消停。他们的恶是有限的、可预测的、可防范的——因为你可以通过利益计算来预判他们的行为。</p><p>但&quot;纯良&quot;的人没有这个上限。因为他们不为自己，所以他们的&quot;奉献&quot;没有终点。罗伯斯庇尔不是为了钱，不是为了女人，不是为了权力——他真心相信自己在缔造一个美德共和国，所以任何阻碍这个目标的人都必须被消灭，包括他的昔日战友丹东。当他自己的脖子搭上断头台时，他仍然相信自己是对的。</p><p><strong>一个为私利作恶的人，你可以通过满足他的私利来制止他。一个为&quot;正义&quot;作恶的人，你没有任何东西可以与他交易——因为他要的不是你的钱，而是你的&quot;正确&quot;。</strong></p><h3 id="二-道德确信消除了自我纠错的可能" tabindex="-1">（二）道德确信消除了自我纠错的可能 <a class="header-anchor" href="#二-道德确信消除了自我纠错的可能" aria-label="Permalink to &quot;（二）道德确信消除了自我纠错的可能&quot;">​</a></h3><p>一个出于私利作恶的人，偶尔也会犹豫：我这么做是不是太过分了？这种犹豫来自利益计算——风险太大了，收益不够了，该收手了。但一个出于道德确信行事的人，他的内心没有这个刹车机制。因为他的良心是清白的——他不是在为自己谋利，他是在&quot;执行正义&quot;。一个良心清白的人，为什么要犹豫？</p><p>这就是为什么&quot;严打&quot;中的许多办案人员，直到今天仍然认为自己没有做错。他们不是不知道有人被冤枉了，而是他们认为&quot;大方向是对的，个别错案在所难免&quot;。这种&quot;大方向正确&quot;的道德确信，比任何自私的动机都更难被挑战——因为你无法用利益来瓦解一个不图利益的人，也无法用道德来谴责一个自认道德的人。</p><p>需要特别指出的是，这里讨论的机制与汉娜·阿伦特笔下的&quot;平庸之恶&quot;（banality of evil）截然不同。阿伦特分析艾希曼时，关注的是&quot;无思&quot;——一种不思考、不判断、只服从的认知惰性。但艾希曼本人并非&quot;纯良的好人误入歧途&quot;：他有着明确的反犹主义意识形态立场，他在法庭上呈现的那副&quot;平庸官僚&quot;面孔，本身就是一种策略性的自我呈现——他刻意把自己装扮成一个&quot;只是执行命令的人&quot;，以逃避个人责任。阿伦特讨论的是&quot;不思考&quot;的恶，本文讨论的是&quot;太确信&quot;的恶——前者是认知惰性，后者是道德狂热。两者的心理机制完全不同，不应混为一谈。</p><h3 id="三-集体共振-纯良的人更容易被动员" tabindex="-1">（三）集体共振：纯良的人更容易被动员 <a class="header-anchor" href="#三-集体共振-纯良的人更容易被动员" aria-label="Permalink to &quot;（三）集体共振：纯良的人更容易被动员&quot;">​</a></h3><p>自私的人是孤立的。一个贪官不会号召别人一起贪，一个骗子不会组建一个&quot;行骗共同体&quot;。他们的恶是个体性的，规模有限。</p><p>但&quot;纯良&quot;的人天然具有集体动员的能力。&quot;把坏人抓起来&quot;是一个极具号召力的口号——它能激发愤怒、制造团结、产生道德优越感。勒庞在《乌合之众》中早就指出：群众最容易被他认为代表某种崇高理想的领袖所打动，而最不容易抵抗的诱惑，就是&quot;为正义而战&quot;的幻觉。当一群人相信自己站在正义的一边时，他们就会做出个体绝不会做出的事情——批斗、举报、暴力——因为他们相信这一切都是&quot;正义的代价&quot;。</p><p>法国大革命时期的&quot;九月屠杀&quot;就是典型案例：1792年9月，巴黎群众在&quot;保卫革命&quot;的口号下，冲进监狱屠杀了1000多名囚犯——其中大多数是普通刑事犯和政治犯，而非他们想象中的&quot;反革命阴谋家&quot;。屠杀者不是职业刽子手，而是普通的市民、手工业者、小店主——他们真心相信自己在&quot;保卫祖国&quot;。</p><h3 id="四-权力乐于征用-纯良-作为合法性外衣" tabindex="-1">（四）权力乐于征用&quot;纯良&quot;作为合法性外衣 <a class="header-anchor" href="#四-权力乐于征用-纯良-作为合法性外衣" aria-label="Permalink to &quot;（四）权力乐于征用&quot;纯良&quot;作为合法性外衣&quot;">​</a></h3><p>权力最喜欢用的合法性外衣，不是暴力，而是&quot;民意&quot;。而&quot;纯良&quot;的人恰恰是&quot;民意&quot;的最佳载体。</p><p>当权力需要推行一项争议性政策时，它不需要自己出面，只需要找到一群&quot;真心相信这件事是对的&quot;的普通人，让他们去执行、去宣传、去辩护。这些普通人不是为了权力，而是为了&quot;正义&quot;——这使得权力的扩张获得了道德光环。</p><p>1983年&quot;严打&quot;期间，大量群众积极参与&quot;揭发检举&quot;，许多人出于朴素的正义感，真心相信自己在&quot;配合政府打击犯罪&quot;。他们的参与本身是真诚的，但正是这种真诚的参与，为权力的过度扩张提供了最有力的合法性背书——&quot;你看，人民群众是拥护的&quot;。</p><p><strong>权力最完美的运作方式，不是强迫你服从，而是让你心甘情愿地服从，并且让你相信这是你自己的选择。</strong></p><h3 id="五-纯良-的恶最难被事后追责" tabindex="-1">（五）&quot;纯良&quot;的恶最难被事后追责 <a class="header-anchor" href="#五-纯良-的恶最难被事后追责" aria-label="Permalink to &quot;（五）&quot;纯良&quot;的恶最难被事后追责&quot;">​</a></h3><p>自私的人作恶后，至少留下了利益链条——钱去了哪里，好处给了谁，一查就清楚。但&quot;纯良&quot;的人作恶后，什么都没有留下——他没有拿一分钱，没有谋一分利，他只是&quot;执行了正义&quot;。你怎么追责一个&quot;动机纯洁&quot;的人？</p><p>这就是为什么&quot;严打&quot;中的许多冤案，至今难以得到彻底纠正。不是因为证据消失了，而是因为当年的办案人员&quot;动机是好的&quot;——他们真心相信自己在保护社会。这种&quot;动机纯洁&quot;成为了一种隐性的免责盾牌：你很难说一个&quot;好人&quot;做了坏事，你只能安慰自己&quot;执行中出了偏差&quot;。</p><p><strong>自私的恶可以被清算，因为利益链条是可见的。&quot;纯良&quot;的恶几乎无法被清算，因为它没有留下任何可追溯的痕迹——除了那些被碾碎的人生。</strong></p><h3 id="五、-结果正义-的幻觉-你以为你在追求正义-其实你在追求报复" tabindex="-1">五、&quot;结果正义&quot;的幻觉：你以为你在追求正义，其实你在追求报复 <a class="header-anchor" href="#五、-结果正义-的幻觉-你以为你在追求正义-其实你在追求报复" aria-label="Permalink to &quot;五、&quot;结果正义&quot;的幻觉：你以为你在追求正义，其实你在追求报复&quot;">​</a></h3><p>&quot;追求结果正义&quot;的人有一个根本性的认知盲区：<strong>他们把&quot;惩罚坏人带来的快感&quot;等同于&quot;正义的实现&quot;。</strong></p><p>心理学研究早就揭示，人类对&quot;报应&quot;的渴望是一种深层的本能反应。当你看到一个&quot;坏人&quot;受到惩罚时，大脑的奖赏回路会被激活——这种快感和吃到甜食、赢得比赛时的快感来自同一个神经回路。这就是为什么&quot;把坏人抓起来&quot;如此令人满足：它不是理性的判断，而是本能的释放。</p><p>但&quot;惩罚坏人带来的快感&quot;和&quot;正义的实现&quot;是两码事。正义要求的是：程序正当、证据充分、比例适当、可救济、可纠错。而&quot;惩罚坏人带来的快感&quot;只要求一件事：<strong>坏人受到惩罚。</strong> 至于这个&quot;坏人&quot;是不是真的是坏人，惩罚的方式是否正当，惩罚的程度是否适当——这些都不重要，重要的是&quot;他受到了惩罚&quot;。</p><p>这就是为什么&quot;严打&quot;期间会出现那么多荒唐案件：一个人因为&quot;看起来像坏人&quot;就被抓了，因为&quot;群众举报&quot;就被判了，因为&quot;从重从快&quot;就被重判了。不是没有人发现其中的问题，而是&quot;惩罚坏人&quot;的快感压过了对程序正义的坚持。</p><p><strong>你以为你在追求正义，其实你在追求报复。而报复从来不需要正义——它只需要一个&quot;坏人&quot;。</strong></p><h3 id="六、历史的判词" tabindex="-1">六、历史的判词 <a class="header-anchor" href="#六、历史的判词" aria-label="Permalink to &quot;六、历史的判词&quot;">​</a></h3><h3 id="法国大革命-美德共和国的血腥实验" tabindex="-1">法国大革命：美德共和国的血腥实验 <a class="header-anchor" href="#法国大革命-美德共和国的血腥实验" aria-label="Permalink to &quot;法国大革命：美德共和国的血腥实验&quot;">​</a></h3><p>罗伯斯庇尔是人类历史上&quot;纯良之恶&quot;的标本级案例。他出身律师，生活简朴，不贪财不好色，被同时代人称为&quot;不可腐蚀者&quot;。他真心相信卢梭的&quot;公意&quot;理论，相信一个共和国必须由美德来维系，而美德的敌人必须被消灭。</p><p>在他的主导下，1793年至1794年的&quot;恐怖统治&quot;期间，革命法庭以&quot;人民的敌人&quot;&quot;共和国的敌人&quot;等极其模糊的罪名，将超过17000人送上断头台。被告的权利被系统性剥夺：1794年6月10日的《牧月22日法令》取消了被告的辩护权，法庭只需&quot;任何类型的证据&quot;即可定罪——甚至仅凭&quot;道德上的确信&quot;即可判决。</p><p>罗伯斯庇尔的悲剧在于：他至死都相信自己是对的。当他在热月政变中被捕、即将被送上断头台时，他仍然在演讲中宣称自己&quot;唯一的激情是正义&quot;。</p><p><strong>一个真心相信自己在缔造天堂的人，最终缔造了地狱。这就是&quot;纯良之恶&quot;的终极悖论。</strong></p><h3 id="_1983年-严打-朴素正义感的制度化灾难" tabindex="-1">1983年&quot;严打&quot;：朴素正义感的制度化灾难 <a class="header-anchor" href="#_1983年-严打-朴素正义感的制度化灾难" aria-label="Permalink to &quot;1983年&quot;严打&quot;：朴素正义感的制度化灾难&quot;">​</a></h3><p>中国1983年&quot;严打&quot;是另一个典型案例。它的起点是真实的：文革结束后社会治安严重恶化，恶性案件频发，公众安全感急剧下降。&quot;从重从快打击刑事犯罪&quot;的号召获得了广泛的民间支持——很多人真心相信，只有严厉打击才能恢复社会秩序。</p><p>但&quot;从重从快&quot;的逻辑一旦启动，就不可避免地走向扩大化——正如前文所述，程序正义被系统性地抛弃，大量轻微违法行为被拔高为刑事犯罪。最终，&quot;严打&quot;不仅没有从根本上解决治安问题，反而制造了大量冤假错案，严重损害了司法公信力。</p><p>而那些当年积极参与&quot;严打&quot;的普通人——举报邻居的、参与公审大会的、为&quot;从重从快&quot;叫好的——他们中的大多数人，今天仍然认为自己没有做错。因为他们&quot;动机是好的&quot;，因为他们&quot;是为了社会安定&quot;。</p><p><strong>这就是&quot;纯良之恶&quot;最可怕的地方：它不需要你变坏，它只需要你&quot;好心&quot;。</strong></p><h3 id="七、为什么-愚蠢-比-恶意-更危险-认知结构的致命差异" tabindex="-1">七、为什么&quot;愚蠢&quot;比&quot;恶意&quot;更危险：认知结构的致命差异 <a class="header-anchor" href="#七、为什么-愚蠢-比-恶意-更危险-认知结构的致命差异" aria-label="Permalink to &quot;七、为什么&quot;愚蠢&quot;比&quot;恶意&quot;更危险：认知结构的致命差异&quot;">​</a></h3><p>现在回到核心问题：为什么&quot;愚蠢的人&quot;比&quot;坏人&quot;可能产生更大的危害？</p><p>这里的&quot;愚蠢&quot;不是智商意义上的，而是认知结构意义上的——它指的是<strong>缺乏反思能力、缺乏对复杂性的认知、缺乏对规则边界的尊重、缺乏对自身判断力的怀疑</strong>。</p><h3 id="一-坏人可预测-愚蠢的人不可预测" tabindex="-1">（一）坏人可预测，愚蠢的人不可预测 <a class="header-anchor" href="#一-坏人可预测-愚蠢的人不可预测" aria-label="Permalink to &quot;（一）坏人可预测，愚蠢的人不可预测&quot;">​</a></h3><p>一个自私的人，你可以通过利益计算来预判他的行为：他贪够了就会收手，他骗完了就会消失，他的恶是有边界的。</p><p>但一个&quot;纯良&quot;的愚蠢者，你无法预判他的行为——因为他不受利益约束，只受&quot;信念&quot;驱动。而信念是可以无限膨胀的。今天他相信&quot;把小偷抓起来&quot;是对的，明天他就可能相信&quot;把说错话的人抓起来&quot;也是对的。每一步都有&quot;正义&quot;的旗号，每一步都不可预测。</p><h3 id="二-坏人知道自己在作恶-愚蠢的人不知道" tabindex="-1">（二）坏人知道自己在作恶，愚蠢的人不知道 <a class="header-anchor" href="#二-坏人知道自己在作恶-愚蠢的人不知道" aria-label="Permalink to &quot;（二）坏人知道自己在作恶，愚蠢的人不知道&quot;">​</a></h3><p>一个坏人做了坏事，至少知道自己在做坏事——这意味着他有被制止的可能：你可以用法律制裁他，用利益交换他，用威慑阻止他。</p><p>但一个&quot;纯良&quot;的人做了坏事，他不认为自己在做坏事。他认为自己在&quot;执行正义&quot;。你怎么制止一个认为自己是对的的人？你无法用法律威慑他（因为他认为自己没有违法），无法用利益交换他（因为他不图利益），无法用道德说服他（因为他认为自己比你有道德）。</p><h3 id="三-坏人是个体的-愚蠢的人是集体的" tabindex="-1">（三）坏人是个体的，愚蠢的人是集体的 <a class="header-anchor" href="#三-坏人是个体的-愚蠢的人是集体的" aria-label="Permalink to &quot;（三）坏人是个体的，愚蠢的人是集体的&quot;">​</a></h3><p>一个坏人作恶，通常是个体行为，影响范围有限。但&quot;纯良&quot;的愚蠢者天然具有集体动员的能力——因为&quot;正义&quot;是最强大的动员工具。当一群&quot;纯良&quot;的人聚集在一起，他们就形成了一种不可阻挡的力量：他们互相强化信念，互相提供道德合法性，互相消除个体的犹豫和怀疑。</p><p>勒庞在《乌合之众》中指出：群体中的个体智力会被严重拉低，但群体的行动力会被急剧放大。当一个群体被&quot;正义&quot;的信念所驱动时，它就会做出个体绝不会做出的事情——因为每个人都相信&quot;大家都在做，所以一定是对的&quot;。</p><h3 id="四-坏人可以被制度约束-愚蠢的人会主动拆毁制度" tabindex="-1">（四）坏人可以被制度约束，愚蠢的人会主动拆毁制度 <a class="header-anchor" href="#四-坏人可以被制度约束-愚蠢的人会主动拆毁制度" aria-label="Permalink to &quot;（四）坏人可以被制度约束，愚蠢的人会主动拆毁制度&quot;">​</a></h3><p>这是最关键的一点。制度的存在，是为了约束所有人的行为——包括好人和坏人。但&quot;纯良&quot;的愚蠢者往往认为制度是&quot;碍事的&quot;：程序太慢了，证据标准太高了，权利保障太多了——这些都妨碍了&quot;正义的实现&quot;。</p><p>所以他们不是被动地违反制度，而是<strong>主动地要求拆毁制度</strong>。他们呼吁&quot;简化程序&quot;，呼吁&quot;降低证据标准&quot;，呼吁&quot;让执法者灵活处理&quot;——每一步都是在拆毁保护他们自己的制度。</p><p>而坏人不会拆毁制度——坏人恰恰需要制度存在，因为制度是他们可以利用的：他们可以贿赂执法者，可以利用程序漏洞，可以利用信息不对称。制度的存在对他们来说不是约束，而是工具。</p><p><strong>真正拆毁制度的，从来不是坏人，而是那些认为制度&quot;碍事&quot;的好人。</strong></p><h2 id="结语-警惕你自己的-纯良" tabindex="-1">结语：警惕你自己的&quot;纯良&quot; <a class="header-anchor" href="#结语-警惕你自己的-纯良" aria-label="Permalink to &quot;结语：警惕你自己的&quot;纯良&quot;&quot;">​</a></h2><p>写到这里，我必须说一句最不舒服的话：<strong>这篇文章不是在说&quot;别人&quot;，而是在说&quot;我们每一个人&quot;。</strong></p><p>因为&quot;纯良之恶&quot;的种子，不在别人身上，在我们每个人心里。</p><p>每当你看到一条新闻，第一反应是&quot;这个人该抓&quot;而不是&quot;证据够不够&quot;的时候——种子就在了。每当你觉得&quot;程序太麻烦了，直接判了算了&quot;的时候——种子就在了。每当你说&quot;虽然手段有点过分，但目的是好的&quot;的时候——种子就在了。每当你说&quot;发动群众判就好了，群众的眼睛是雪亮的&quot;的时候——种子就在了。</p><p>哈耶克在《通往奴役之路》的题记中引用了托克维尔的话：&quot;谁在自由中寻求自由本身以外的其他东西，谁就只配受奴役。&quot;但同样可以说：<strong>谁在正义中寻求正义本身以外的其他东西——快感、安全感、道德优越感——谁就已经偏离了正义。</strong></p><p>通往地狱的路，从来不是由坏人铺就的。坏人只是在地狱里住了下来。</p><p><strong>通往地狱的路，是由那些真心相信自己是在铺通往天堂之路的人，一块砖一块砖铺就的。</strong></p><p>贝卡里亚在260年前就说过：法律应当是&quot;一部庄重的公共典籍&quot;，而非&quot;一本家用私书&quot;。富勒在60年前就说过：缺乏明确性的规则根本就不是法律。孟德斯鸠在300年前就说过：模糊的法律是专制政体的标志。</p><p>而今天，一个写作者用一篇文章去讨论这些命题，然后被一个&quot;可能引起争议&quot;的通知限流——这个通知本身，就是对这些命题最鲜活的当代注脚。</p><p><strong>明确的标准再烂，也比没有标准强。因为明确的规则是约束权力的笼子，模糊的规则是给权力开的后门。</strong></p><p>而每一个替&quot;模糊规则&quot;辩护的人，都是在替权力拆锁。每一个喊&quot;发动群众判案&quot;的人，都是在把那根绑住奥德修斯的绳子解开——然后在塞壬的歌声里，以为自己在驶向天堂。</p><p>你不是在保护大众。你是在替一个随时可能碾碎你的权力结构做辩护，还觉得自己挺理性、挺务实。</p><p>醒醒吧。</p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2076830346293798459" target="_blank" rel="noreferrer">查看原文</a>（4 赞）</p></blockquote>',260)])])}const d=o(r,[["render",p]]);export{g as __pageData,d as default};
